String hashPassword(String password, byte[] salt) throws NoSuchAlgorithmException {
    MessageDigest digest = MessageDigest.getInstance("SHA-256"); // ZAPROJEKTOWANY zeby byc szybki!
    digest.update(salt);
    return HexFormat.of().formatHex(digest.digest(password.getBytes()));
