// DOBRZE: PBKDF2 z duza liczba iteracji - CELOWO wolny, trudny do zmasowanego brute-force
String hashPasswordProperly(String password, byte[] salt) throws Exception {
    var spec = new javax.crypto.spec.PBEKeySpec(password.toCharArray(), salt, 210_000, 256);
    var factory = javax.crypto.SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
    byte[] hash = factory.generateSecret(spec).getEncoded();
    return HexFormat.of().formatHex(hash);
} // 210 000 iteracji = kazda proba MUSI wykonac ta sama, kosztowna prace 210 000 razy
